{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공영 노외주차장 이용 안내표지에 가산금 징수 기준 표시 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공영 노외주차장의 이용 안내표지에는 가산금 징수에 관한 사항을 기재해야 합니다. 이는 제19조에 따라 제15조제2항을 준용하기 때문이며, 제15조제2항제2호에서 가산금 징수에 관한 사항을 안내표지에 기재할 사항으로 정하고 있습니다.",
          "b_ids": "주차장:제19조, 주차장:제15조제2항, 주차장:제15조제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "공영 노외주차장 이용 안내표지 상단에 표시해야 하는 주체",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공영 노외주차장의 이용 안내표지 상단에는 시 또는 관리수탁자의 표시를 해야 합니다. 제19조에서 공영노외주차장의 안내표지는 제15조제2항을 준용하되, 그 표지 상단에 시 또는 관리수탁자의 표시를 하여야 한다고 규정하고 있습니다.",
          "b_ids": "주차장:제19조"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
